using System;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Drawing;using System.Drawing.Drawing2D;
namespace FortsStudio {
 public static partial class Exporter {
  static string TemplateText(Project p,Entity e){var t=Catalog.Get(e);string list=File.ReadAllText(Path.Combine(p.GameRoot,"data",Catalog.TemplateListPath(t)));string entry=Catalog.LuaTable(list,t.Key);if(e.Kind=="materials"){string parent=t.Key=="armour"?"Armor":"Bracing";var m=Regex.Match(list,@"(?m)^"+parent+@"\s*=\s*\{");if(m.Success)entry+="\n"+Catalog.Balanced(list,list.IndexOf('{',m.Index));}return t.Script.Length>0?File.ReadAllText(Path.Combine(p.GameRoot,"data",t.Script)):entry;}
  static string TemplateEffect(Project p,Entity e,string name,string fallback){var m=Regex.Match(TemplateText(p,e),"\\b"+name+"\\s*=\\s*\"([^\"]+)\"");return m.Success?m.Groups[1].Value:fallback;}
  static string AudioEffect(string root,string key,AudioClip clip,string source){string media="";bool custom=clip!=null&&clip.Data.Length>0;double volume=clip==null?1:clip.Volume;if(custom){string ext=Path.GetExtension(clip.FileName).ToLowerInvariant();if(ext!=".wav"&&ext!=".mp3")throw new Exception("Допустимы только WAV и MP3: "+clip.FileName);media="effects/media/"+key+ext;Bytes(root,media,Assets.DataBytes(clip.Data));}string file="effects/"+key+".lua";var sb=new StringBuilder();if(source.Length>0)sb.Append("dofile("+Q(source)+")\n");else sb.Append("LifeSpan = "+N(Math.Max(.1,clip==null?2:clip.Duration)+.05)+"\nEffects = {}\n");
   if(custom||source.Length==0){sb.Append("SoundEvent = ''\nEffects = Effects or {}\nfor i = #Effects,1,-1 do if Effects[i].Type == 'sound' then table.remove(Effects,i) end end\n");if(custom)sb.Append("table.insert(Effects, { Type = 'sound', TimeToTrigger = 0, LocalPosition = { x = 0, y = 0, z = 0 }, Sound = path .. "+Q("/"+media)+", Volume = "+N(volume)+" })\n");}
   else{sb.Append("local fms_event = SoundEvent\nSoundEvent = ''\nEffects = Effects or {}\nlocal fms_found = false\nfor _,e in ipairs(Effects) do if e.Type == 'sound' then e.Volume = (e.Volume or 1) * "+N(volume)+" fms_found = true end end\nif not fms_found then table.insert(Effects, { Type = 'sound', TimeToTrigger = 0, LocalPosition = { x = 0, y = 0, z = 0 }, Sound = fms_event or "+Q(source.EndsWith(".lua")?source.Substring(0,source.Length-4):source)+", Volume = "+N(volume)+" }) end\n");}Write(root,file,sb.ToString());return file;}
  static AudioClip Primary(Entity e){return new AudioClip{Data=e.Sound,FileName=e.SoundName,Volume=e.SoundVolume};}
  static bool CustomVolume(AudioClip clip){return clip!=null&&(clip.Data.Length>0||Math.Abs(clip.Volume-1)>.0001);}
  static string MaterialResources(Project p,string root,Entity e){if(!CustomVolume(e.DestroyAudio))return "";string fx=AudioEffect(root,e.Key+"_destroy",e.DestroyAudio,TemplateEffect(p,e,"DestroyEffect","effects/bracing_destroy.lua"));return "item.DestroyEffect = path .. "+Q("/"+fx)+"\n";}
  static string ProjectileResources(Project p,string root,Entity e){var clip=Primary(e);if(!CustomVolume(clip))return "";var effects=new HashSet<string>(Regex.Matches(TemplateText(p,e),"\"(effects/[^\"]+\\.lua)\"").Cast<Match>().Select(m=>m.Groups[1].Value));foreach(var c in p.Chains.Where(c=>c.Source==e.Key&&c.Event=="native_impact"))foreach(var b in AllBlocks(c.Blocks).Where(b=>b.Type=="effect"&&b.Value.Length>0))effects.Add(b.Value);effects.Add("effects/impact_heavy.lua");var sb=new StringBuilder("local fms_impact_audio = {}\n");int i=0;foreach(string fx in effects){string wrapper=AudioEffect(root,e.Key+"_impact_"+i++,clip,fx);sb.Append("fms_impact_audio["+Q(fx)+"] = path .. "+Q("/"+wrapper)+"\n");}sb.Append("item.Effects = item.Effects or {}\nitem.Effects.Impact = item.Effects.Impact or {}\nfor k,v in pairs(item.Effects.Impact) do if type(v) == 'string' then item.Effects.Impact[k] = fms_impact_audio[v] or v elseif type(v) == 'table' and v.Effect then v.Effect = fms_impact_audio[v.Effect] or v.Effect end end\n");return sb.ToString();}
  static string ScriptResources(Project p,string root,Entity e){var sb=new StringBuilder();if(CustomVolume(Primary(e))){string variable=e.Kind=="weapons"?"FireEffect":"ConstructEffect",fallback=e.Kind=="weapons"?"effects/fire_cannon.lua":"effects/device_construct.lua";string fx=AudioEffect(root,e.Key+"_primary",Primary(e),TemplateEffect(p,e,variable,fallback));sb.Append(variable+" = path .. "+Q("/"+fx)+"\n");}if(e.Kind=="weapons")sb.Append("RetriggerFireEffect = "+(e.SoundEachShot?"true":"false")+"\nRetriggerFireEffectOnce = false\n");if(CustomVolume(e.DestroyAudio)){string fx=AudioEffect(root,e.Key+"_destroy",e.DestroyAudio,TemplateEffect(p,e,"DestroyEffect","effects/device_explode.lua"));sb.Append("DestroyEffect = path .. "+Q("/"+fx)+"\n");}
   if(e.Kind=="devices"&&(e.Texture.Length>0||e.BuildStages.Count>0)){var stages=e.BuildStages.Count>0?e.BuildStages.OrderBy(s=>s.Progress).ToList():new List<BuildStage>{new BuildStage{Progress=0,Image=e.Texture}};Bitmap original=Assets.Body(e,p.GameRoot);if(original==null)throw new Exception("Не прочитан спрайт "+e.NameRu);Bitmap first=Assets.Image(stages[0].Image.Length>0?stages[0].Image:e.Texture,p.GameRoot)??original;
    // Bake the requested model size into custom textures. Forts' global Scale
    // does not reliably resize a replaced Root. One bitmap pixel is 0.5 world units.
    Size dimensions=Raster.ModelSize(first,e.V("Scale",1));int width=dimensions.Width,height=dimensions.Height;sb.Append("Scale = 1\n");
    string prefix="fms_"+e.Key+"_stage_";for(int i=0;i<stages.Count;i++){var image=Assets.Image(stages[i].Image.Length>0?stages[i].Image:e.Texture,p.GameRoot)??original;using(var canvas=Raster.Fit(image,width,height)){string file="assets/"+e.Key+"-stage-"+i+".tga";Bytes(root,file,Assets.Tga(canvas,0));sb.Append(Sprite(prefix+i,file));}}
    sb.Append("Root = { Name = 'FMSDevice', Angle = 0, Pivot = { 0, -0.5 }, PivotOffset = { 0, 0 }, Sprite = "+Q(prefix+"0")+", UserData = 0, ChildrenInFront = { { Name = 'Head', Angle = 0, Pivot = { 0, 0 }, PivotOffset = { 0, 0 }, UserData = 0 }");for(int i=1;i<stages.Count;i++)sb.Append(", { Name = "+Q("BuildStage"+i)+", Angle = 0, Pivot = { 0, 0 }, PivotOffset = { 0, 0 }, Sprite = "+Q(prefix+i)+", UserData = "+stages[i].Progress+" }");sb.Append(" } }\n");}
   return sb.ToString();}
  static void ExportAudioResources(Project p,string root){foreach(var b in p.Chains.Where(c=>c.Enabled).SelectMany(c=>AllBlocks(c.Blocks)).Where(b=>b.Type=="sound"||b.Type=="loop_sound")){var a=p.Sounds.FirstOrDefault(x=>x.Id==b.Value);if(a!=null&&a.Data.Length>0)AudioEffect(root,"block_"+b.Id,new AudioClip{Data=a.Data,FileName=a.FileName,Duration=a.Duration,Volume=a.Volume*Math.Max(0,Math.Min(200,b.Number))/100},"");}foreach(var s in p.Sounds)if(s.Data.Length>0)AudioEffect(root,"lib_"+s.Id,s,"");foreach(var e in p.Entities){if(e.WorkAudio.Data.Length>0)AudioEffect(root,e.Key+"_work",e.WorkAudio,"");if(e.FlightAudio.Data.Length>0)AudioEffect(root,e.Key+"_flight",e.FlightAudio,"");}}
  public static IEnumerable<Block> AllBlocks(IEnumerable<Block> blocks){foreach(var b in blocks){yield return b;foreach(var ch in AllBlocks(b.Children))yield return ch;foreach(var ch in AllBlocks(b.Otherwise))yield return ch;}}
 }
}
